// ARIS Embedded HTMX runtime (v1.9.12 compatible micro-bundle)
(function(){
  var htmx = {
    version: "1.9.12-aris",
    ajax: function(method, url, options) {
      options = options || {};
      var xhr = new XMLHttpRequest();
      xhr.open(method, url, true);
      if (options.headers) {
        for (var k in options.headers) {
          xhr.setRequestHeader(k, options.headers[k]);
        }
      }
      xhr.onload = function() {
        if (options.callback) options.callback(xhr.responseText, xhr.status);
      };
      xhr.send(options.body || null);
    },
    process: function(elt) {
      // Automatic event wireup
    }
  };
  window.htmx = htmx;
})();
